import { bleCrc, decode } from '../../src/lib/decoder';

// Bluetooth Core 6.1, Vol 6 Part C 4.3.1 and 4.3.2.
// Published CRCs are constants, not generated by the code under test.
export const sigData = [0x2b, 0x19, 0x08, 0xaa, 0x16, 5, 1, 2, 3, 4, 5, 0x45, 0xd0, 0xd2];
export const sigControl = [
  0x42, 0x3c, 0x17, 0xaa, 0x3b, 8, 0x85, 1, 0xdb, 0xff, 0xff, 0xff, 1, 0x21, 0x43, 0x39, 0xe2, 0x94,
];
export function connectionFrame() {
  const pdu = [
    0x45, 34, 11, 12, 13, 14, 15, 0xc0, 1, 2, 3, 4, 5, 0xc6, 0x2b, 0x19, 0x08, 0xaa, 0x81, 0xc1,
    0xc4, 2, 3, 0, 24, 0, 0, 0, 200, 0, 0xff, 0xff, 0xff, 0xff, 0x1f, 5,
  ];
  return decode([0xd6, 0xbe, 0x89, 0x8e, ...pdu, ...bleCrc(pdu)], 'ble', {
    id: 1,
    time: 1,
    channel: 37,
  });
}
